INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4061705, 581464, 80807, '<td valign="top">The man made lights distract from an otherwise scenic photo.  Still an above average shot, very nice</td>', 'The man made lights distract from an otherwise scenic photo.  Still an above average shot, very nice', '2007-09-05 14:18:24.000000', NULL, 1),
(4061726, 581167, 80807, '<td valign="top">I have no critical things to say, just a great big WOW!!!!!!</td>', 'I have no critical things to say, just a great big WOW!!!!!!', '2007-09-05 14:26:50.000000', NULL, 1),
(4061732, 580188, 80807, '<td valign="top">too much blur</td>', 'too much blur', '2007-09-05 14:28:38.000000', NULL, 1),
(4061772, 582146, 28742, '<td valign="top">That''s not half bad! :)</td>', 'That''s not half bad! :)', '2007-09-05 14:38:24.000000', NULL, 1),
(4061789, 581603, 66193, '<td valign="top">good control over exposure.  But, there''s a lot to look at here!  Maybe a closer crop to the Ferrari would have made a stronger subject.</td>', 'good control over exposure.  But, there''s a lot to look at here!  Maybe a closer crop to the Ferrari would have made a stronger subject.', '2007-09-05 14:40:37.000000', NULL, 1),
