(4061796, 581665, 28742, '<td valign="top">Would you have aimed your camera a little lower and to the left, I''d give you an extra point. The grill is also blown out a bit (you''ll probably hear that alot). Overall decent though.</td>', 'Would you have aimed your camera a little lower and to the left, I''d give you an extra point. The grill is also blown out a bit (you''ll probably hear that alot). Overall decent though.', '2007-09-05 14:41:25.000000', NULL, 1),
(4061798, 581630, 66193, '<td valign="top">doesn''t convey power to me.  I like the colors though.</td>', 'doesn''t convey power to me.  I like the colors though.', '2007-09-05 14:41:46.000000', NULL, 1),
(4061800, 580211, 28742, '<td valign="top">Is that the famous "Shoehorn Frog"? ;-)</td>', 'Is that the famous "Shoehorn Frog"? ;-)', '2007-09-05 14:42:12.000000', NULL, 1),
(4061801, 582230, 66193, '<td valign="top">not technically perfect, but that fits the image well!</td>', 'not technically perfect, but that fits the image well!', '2007-09-05 14:42:22.000000', NULL, 1),
