(4066495, 581464, 66038, '<td valign="top">I would have loved to have seen this photo without the lightpost in it.<br/> It distracts from the intricate details of those magnificent clouds.</td>', 'I would have loved to have seen this photo without the lightpost in it. It distracts from the intricate details of those magnificent clouds.', '2007-09-06 19:55:51.000000', NULL, 1),
(4066522, 579966, 63269, '<td valign="top">Awesome. <i>Very </i> powerful indeed - this is just glorious. :) I love the colors and the deep contrasts.</td>', 'Awesome. Very  powerful indeed - this is just glorious. :) I love the colors and the deep contrasts.', '2007-09-06 20:06:04.000000', NULL, 1),
(4066543, 580469, 74534, '<td valign="top">Nice colors and reflections. Good composition - just don''t think subject is very interesting. The litle background that''s showing is also uninteresting.</td>', 'Nice colors and reflections. Good composition - just don''t think subject is very interesting. The litle background that''s showing is also uninteresting.', '2007-09-06 20:16:05.000000', NULL, 1),
(4066546, 582195, 74534, '<td valign="top">I don''t see the "Power" connection. Also, blown out sky is annoying, the water looks overexposed as well and the image oversharpened.</td>', 'I don''t see the "Power" connection. Also, blown out sky is annoying, the water looks overexposed as well and the image oversharpened.', '2007-09-06 20:17:11.000000', NULL, 1),
