(4066580, 582256, 74534, '<td valign="top">DNMC IMO, plus lighting is rather bad blowing out part of the image and leaving the rest too dark.</td>', 'DNMC IMO, plus lighting is rather bad blowing out part of the image and leaving the rest too dark.', '2007-09-06 20:27:28.000000', NULL, 1),
(4066609, 581227, 63503, '<td valign="top">This is a great display of power by a car; I think you could improve the picture using a different crop and composition, with less foreground and without cropping off the front of the camaro. A perspective shot with lots of smoke in the foreground and just a hint of the car accelerating away would be even better.</td>', 'This is a great display of power by a car; I think you could improve the picture using a different crop and composition, with less foreground and without cropping off the front of the camaro. A perspective shot with lots of smoke in the foreground and just a hint of the car accelerating away would be even better.', '2007-09-06 20:37:18.000000', NULL, 1),
(4066628, 582335, 63503, '<td valign="top">Gorgeous car but less than ideal portrait of it. IMO you could improve it by using a lens with shorter focus and a larger f stop, I don''t think that the shallow dof in you picture is flattering to this otherwise deserving animal.</td>', 'Gorgeous car but less than ideal portrait of it. IMO you could improve it by using a lens with shorter focus and a larger f stop, I don''t think that the shallow dof in you picture is flattering to this otherwise deserving animal.', '2007-09-06 20:41:07.000000', NULL, 1),
(4066647, 581854, 63503, '<td valign="top">Nice action shot. I am sure you tried it without cropping the guy''s head and liked this better, but I still wonder.</td>', 'Nice action shot. I am sure you tried it without cropping the guy''s head and liked this better, but I still wonder.', '2007-09-06 20:46:19.000000', NULL, 1),
(4066672, 582426, 63503, '<td valign="top">I don''t get the tittle but like the picture, and I''d like it even better with a bit better focus and without the blown-out highlights. The limited dose of red contrasts very nicely with the greasy dark surroundings.</td>', 'I don''t get the tittle but like the picture, and I''d like it even better with a bit better focus and without the blown-out highlights. The limited dose of red contrasts very nicely with the greasy dark surroundings.', '2007-09-06 20:53:14.000000', NULL, 1),
(4066673, 581707, 63503, '<td valign="top">Nice setup!!</td>', 'Nice setup!!', '2007-09-06 20:53:49.000000', NULL, 1),
