(4066689, 581816, 56849, '<td valign="top">?</td>', '?', '2007-09-06 20:59:19.000000', NULL, 1),
(4066702, 582290, 63503, '<td valign="top">Great expression and crop !! B&amp;W is a great way of dealing with what is likely to to be a distracting background in color. The light to her left side is a bit too hard, the resulting hard shadow of her nose does not work for my taste. Filling light to her right or light diffuser to her left would have helped. I am giving you a 7, would have been an 8 or 9 with better lighting.</td>', 'Great expression and crop !! B&W is a great way of dealing with what is likely to to be a distracting background in color. The light to her left side is a bit too hard, the resulting hard shadow of her nose does not work for my taste. Filling light to her right or light diffuser to her left would have helped. I am giving you a 7, would have been an 8 or 9 with better lighting.', '2007-09-06 21:04:01.000000', NULL, 1),
(4066705, 581145, 63503, '<td valign="top">Great action shot and panning!! it does convey the feeling of power (8)</td>', 'Great action shot and panning!! it does convey the feeling of power (8)', '2007-09-06 21:04:45.000000', NULL, 1),
(4066717, 582162, 63503, '<td valign="top">Beautiful model and great image of her. I think the high key white background is overwhelming, contrasts excesively with her dark skin and detracts from the image, I am giving it a 6, would have been an easy 8 with better background, sorry.</td>', 'Beautiful model and great image of her. I think the high key white background is overwhelming, contrasts excesively with her dark skin and detracts from the image, I am giving it a 6, would have been an easy 8 with better background, sorry.', '2007-09-06 21:09:59.000000', NULL, 1),
(4066719, 581516, 77724, '<td valign="top">The heads turn an interesting photo into just a snap</td>', 'The heads turn an interesting photo into just a snap', '2007-09-06 21:10:36.000000', NULL, 1),
(4066721, 582550, 77724, '<td valign="top">Nice capture.</td>', 'Nice capture.', '2007-09-06 21:11:49.000000', NULL, 1),
(4066723, 582316, 17513, '<td valign="top">fantastic shot</td>', 'fantastic shot', '2007-09-06 21:12:06.000000', NULL, 1),
