(4082997, 581517, 66384, '<td valign="top">Beautiful. The B&amp;W is really nice. I don''t understand all those low votes -- one or two are sort of normal, but this is ridiculous.</td>', 'Beautiful. The B&W is really nice. I don''t understand all those low votes -- one or two are sort of normal, but this is ridiculous.', '2007-09-12 01:11:21.000000', NULL, 0),
(4082998, 581928, 25355, '<td valign="top">I would never have thought to use a polariser at night; good choice.<br/>Congratulations on the electric Blue.</td>', 'I would never have thought to use a polariser at night; good choice.Congratulations on the electric Blue.', '2007-09-12 01:11:34.000000', NULL, 0),
(4083002, 580661, 61961, '<td valign="top">All right, Sue!  Nice image, great sky.  The building looks like a giant drill.</td>', 'All right, Sue!  Nice image, great sky.  The building looks like a giant drill.', '2007-09-12 01:12:21.000000', NULL, 0),
(4083003, 581636, 62318, '<td valign="top">FYI, this shot shows a better example of "power" than my own. I think it is a wonderful working shot. A beauty and sorely under rated.</td>', 'FYI, this shot shows a better example of "power" than my own. I think it is a wonderful working shot. A beauty and sorely under rated.', '2007-09-12 01:12:23.000000', NULL, 0),
