(4083010, 581517, 60862, '<td valign="top">A gorgeous B&amp;W landscape.  Congrats!</td>', 'A gorgeous B&W landscape.  Congrats!', '2007-09-12 01:14:04.000000', NULL, 0),
(4083013, 582220, 67697, '<td valign="top">Great idea for the challenge theme.  Pretty sky (nice blue!).  Something I would like to have seen different, and it might not be possible, is actually a different angle.  What I mean is that you would either have to take this from a different height or possibly further back so that the camera is not pointed directly up.  Hard to explain but I feel that you would get a better sense of power if you could get a better look at the face of the statue.</td>', 'Great idea for the challenge theme.  Pretty sky (nice blue!).  Something I would like to have seen different, and it might not be possible, is actually a different angle.  What I mean is that you would either have to take this from a different height or possibly further back so that the camera is not pointed directly up.  Hard to explain but I feel that you would get a better sense of power if you could get a better look at the face of the statue.', '2007-09-12 01:14:25.000000', NULL, 0),
(4083014, 580683, 772, '<td valign="top">I didn''t look at this challenge during voting, but man... this photo is wicked!  Is this one of those photos capturing the moment where the plane goes supersonic?</td>', 'I didn''t look at this challenge during voting, but man... this photo is wicked!  Is this one of those photos capturing the moment where the plane goes supersonic?', '2007-09-12 01:14:30.000000', NULL, 0),
