(4097172, 582272, 83455, '<td valign="top">Conratulations on the ribbon. Good PP work and excellent note.</td>', 'Conratulations on the ribbon. Good PP work and excellent note.', '2007-09-17 18:07:20.000000', NULL, 0),
(4097396, 581928, 55838, '<td valign="top">Awesome shot Tate!  Congratulations!!  I imagine your knees did feel a bit fuzzy as you were taking this shot but it was sure worth it.  The man who will do anything for his art (I know - I''ve been there to see it!!)  : )</td>', 'Awesome shot Tate!  Congratulations!!  I imagine your knees did feel a bit fuzzy as you were taking this shot but it was sure worth it.  The man who will do anything for his art (I know - I''ve been there to see it!!)  : )', '2007-09-17 20:11:44.000000', NULL, 0),
